import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import Axios from 'axios';
import { Chart, registerables } from 'chart.js';
import './course.css';

// Register Chart.js components
Chart.register(...registerables);

function CourseSearch() {
  const [data, setData] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const chartRef = useRef(null);
  const chartInstanceRef = useRef(null);

  // Fetch all records
  const fetchAllData = async () => {
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.get('http://localhost:3002/details');
      const users = response.data.users || [];
      setData(users);
      const uniqueCourses = [...new Set(users.map((user) => user.course))].sort();
      setCourses(uniqueCourses);
      setLoading(false);
      // Destroy chart if it exists when showing all courses
      if (chartInstanceRef.current) {
        chartInstanceRef.current.destroy();
        chartInstanceRef.current = null;
      }
    } catch (error) {
      setLoading(false);
      setMessage('Error fetching data. Please try again.');
      console.error('Error fetching all data:', error);
    }
  };

  // Fetch data for a specific course
  const fetchCourseData = async (course) => {
    if (!course) return;
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.post('http://localhost:3002/course', { course });
      const users = response.data.users || [];
      setData(users);
      setLoading(false);
      if (users.length === 0) {
        setMessage('No records found for this course.');
      }
      updateChart(users, course);
    } catch (error) {
      setLoading(false);
      setMessage('Error searching course. Please try again.');
      console.error('Error searching course:', error);
    }
  };

  // Update bar chart
  const updateChart = (users, course) => {
    if (chartInstanceRef.current) {
      chartInstanceRef.current.destroy();
    }

    const ctx = chartRef.current.getContext('2d');
    const districtData = {};
    users.forEach((user) => {
      districtData[user.district] = (districtData[user.district] || 0) + (user.students || 0);
    });

    const labels = Object.keys(districtData);
    const studentCounts = Object.values(districtData);

    chartInstanceRef.current = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: 'Number of Students',
          data: studentCounts,
          backgroundColor: 'rgba(37, 99, 235, 0.6)',
          borderColor: 'rgba(37, 99, 235, 1)',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        scales: {
          y: {
            beginAtZero: true,
            title: { display: true, text: 'Students' }
          },
          x: {
            title: { display: true, text: 'District' }
          }
        },
        plugins: {
          legend: { display: false },
          title: {
            display: true,
            text: `Students in ${course} by District`,
            font: { size: 16 }
          }
        }
      }
    });
  };

  // Handle course selection
  const handleCourseChange = (event) => {
    const course = event.target.value;
    setSelectedCourse(course);
    if (course === '') {
      fetchAllData();
    } else {
      fetchCourseData(course);
    }
  };

  // Initial fetch and cleanup
  useEffect(() => {
    fetchAllData();
    return () => {
      if (chartInstanceRef.current) {
        chartInstanceRef.current.destroy();
      }
    };
  }, []);

  return (
    <div className="app-container">
      
      <div className="content-container">
        <div className="course-search-card">
          <h2 className="title">Course Search</h2>
          <div className="form-group">
            <label htmlFor="course">Select Course</label>
            <select
              id="course"
              value={selectedCourse}
              onChange={handleCourseChange}
              disabled={loading}
              className="course-select"
            >
              <option value="">All Courses</option>
              {courses.map((course, index) => (
                <option key={index} value={course}>
                  {course}
                </option>
              ))}
            </select>
          </div>

          {message && (
            <div className={`message ${message.includes('Error') ? 'error' : 'info'}`}>
              {message}
            </div>
          )}

          {loading ? (
            <div className="loading">Loading...</div>
          ) : (
            <div className="table-container">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>District</th>
                    <th>Stream & Subjects</th>
                    <th>Course</th>
                    <th>Z-Range</th>
                    <th>Students</th>
                  </tr>
                </thead>
                <tbody>
                  {data.map((row) => (
                    <tr key={row._id}>
                      <td>{row.district}</td>
                      <td>
                        <div>{row.stream}</div>
                        <div>Subject 1: {row.subject1}</div>
                        <div>Subject 2: {row.subject2}</div>
                        <div>Subject 3: {row.subject3}</div>
                      </td>
                      <td>{row.course}</td>
                      <td>{row.zValue1} - {row.zValue2}</td>
                      <td>{row.students}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {selectedCourse && !loading && (
            <div className="chart-container">
              <canvas ref={chartRef}></canvas>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default CourseSearch;
